<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {ArrowLeft,Plus,KeyRound,Check} from 'lucide-vue-next'
import {useLocal} from '../stores/local'
import type {Document,ProviderConfiguration} from '../domain/local-contract'
import {TEXT_PRESETS} from '../provider-adapters/presets'
import {endpoint} from '../provider-adapters/text'
import {configuredModels,type ModelDefaults} from '../repositories/local-models'
const store=useLocal(),models=ref<Document<ProviderConfiguration>[]>([]),editing=ref<ProviderConfiguration|null>(null),id=ref(''),revision=ref(0),defaults=ref<Document<ModelDefaults>|null>(null),selected=ref('opencode-go-mimo'),error=ref(''),busy=ref(false)
async function load(){if(!store.vault)return;models.value=await configuredModels(store.vault);defaults.value=await store.vault.read<ModelDefaults>('settings:models')}
function create(){editing.value=JSON.parse(JSON.stringify(TEXT_PRESETS.find(p=>p.id===selected.value)!));id.value='model:'+crypto.randomUUID();editing.value!.id=id.value;revision.value=0;error.value=''}
function edit(row:Document<ProviderConfiguration>){editing.value=JSON.parse(JSON.stringify(row.value));id.value=row.id;revision.value=row.revision;error.value=''}
async function save(){const vault=store.vault,profile=editing.value;if(!vault||!profile)return;busy.value=true;error.value='';try{endpoint({...profile,revision:revision.value});if(!profile.modelId.trim())throw new Error('请填写模型 ID');const documents=[{kind:'settings' as const,id:id.value,expectedRevision:revision.value,value:profile}];if(!defaults.value?.value.slots.text)documents.push({kind:'settings',id:'settings:models',expectedRevision:defaults.value?.revision||0,value:{slots:{text:id.value}} as any});await vault.commitBundle(crypto.randomUUID(),documents);editing.value=null;await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function makeDefault(row:Document<ProviderConfiguration>){if(!store.vault)return;busy.value=true;try{await store.vault.commit(crypto.randomUUID(),'settings','settings:models',defaults.value?.revision||0,{slots:{...defaults.value?.value.slots,text:row.id}});await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(()=>void load().catch(e=>error.value=(e as Error).message))
</script>
<template><section><div class="final-page-heading"><div class="final-heading-copy"><RouterLink to="/local/settings" class="final-text-link"><ArrowLeft :size="17"/>我的</RouterLink><h1>模型</h1><RouterLink to="/local/settings/media" class="final-text-link">媒体通道</RouterLink></div><button v-if="editing" @click="editing=null">返回列表</button></div><p v-if="error" class="final-error" role="alert">{{error}}</p><form v-if="editing" class="final-card-form" @submit.prevent="save"><label>名称<input v-model="editing.name" required maxlength="120"></label><label>文本协议<select v-model="editing.protocol"><option value="chat-completions">Chat Completions</option><option value="responses">Responses</option><option value="anthropic">Anthropic Messages</option><option value="gemini">Gemini Generate Content</option></select></label><label>API 地址<input v-model="editing.baseUrl" required autocomplete="off" spellcheck="false"></label><label>模型 ID<input v-model="editing.modelId" required autocomplete="off" spellcheck="false"></label><label>API Key<input v-model="editing.key" type="password" autocomplete="new-password" spellcheck="false"></label><details class="final-model-advanced"><summary>上限与请求设置</summary><label>上下文上限（自行确认）<input v-model.number="editing.contextLimit" type="number" min="1024" max="4000000" required></label><label>单次输出上限<input v-model.number="editing.outputLimit" type="number" min="1" max="100000" required></label><label>设备每日调用上限<input v-model.number="editing.dailyCalls" type="number" min="1" max="10000" required></label><label>首包等待 · 毫秒<input v-model.number="editing.firstPacketMs" type="number" min="100" max="3600000"></label><label>片段空闲 · 毫秒<input v-model.number="editing.idleMs" type="number" min="100" max="3600000"></label><label>总等待 · 毫秒<input v-model.number="editing.totalMs" type="number" min="100" max="3600000"></label><label>输出字段<select v-model="editing.outputParameter"><option value="max_tokens">max_tokens</option><option value="max_completion_tokens">max_completion_tokens</option></select></label><label class="final-check"><input v-model="editing.includeUsage" type="checkbox">请求流式用量（兼容协议）</label><label v-if="editing.protocol==='responses'" class="final-check"><input v-model="editing.queryStoredResponse" type="checkbox">允许供应商存储结果，断线后仅查询原请求</label><label class="final-check"><input v-model="editing.enabled" type="checkbox">启用</label></details><p class="final-subtle">Key 加密保存在此私人库。请求从本机直连所填地址；跨域限制由供应商决定。</p><button class="final-primary" :disabled="busy">保存配置</button></form><template v-else><div class="final-model-create"><label>添加供应商<select v-model="selected"><option v-for="preset in TEXT_PRESETS" :key="preset.id" :value="preset.id">{{preset.name}}</option></select></label><button class="final-primary" @click="create"><Plus :size="18"/>添加</button></div><div v-if="!models.length" class="final-empty"><KeyRound :size="36"/><h2>选择你的文本模型</h2><button @click="create">配置 MiMo 2.6 Flash</button></div><div v-else class="final-settings"><article v-for="model in models" :key="model.id" class="final-setting-card"><h2>{{model.value.name}}</h2><p class="final-subtle">{{model.value.modelId}} · {{model.value.protocol}}</p><p v-if="defaults?.value.slots.text===model.id" class="final-subtle"><Check :size="16"/>文本默认</p><div class="final-grid-actions"><button @click="edit(model)">编辑</button><button :disabled="busy||!model.value.enabled||defaults?.value.slots.text===model.id" @click="makeDefault(model)">设为默认</button></div></article></div></template></section></template>
